import{_ as i,l,o as e,c as n,v as t,p as s,x as r,d,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"k-d 树","description":"","frontmatter":{"title":"k-d 树","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/kd-tree.md","filePath":"cs/kd-tree.md","lastUpdated":1789023840000}'),c={name:"cs/kd-tree.md"};function B(m,a,E,_,k,A){const o=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="k-d-树" tabindex="-1">k-d 树 <a class="header-anchor" href="#k-d-树" aria-label="Permalink to &quot;k-d 树&quot;">​</a></h1><div class="epigraph"><p>各层轮换轴，用中位数把点集切开；范围查询在包围盒与查询矩形不相交时剪枝。</p><footer>—— 据 Bentley, Multidimensional Binary Search Trees Used for Associative Searching, CACM 1975；Preparata and Shamos 整理</footer></div><p><a href="/cs/interval-tree">上一课</a> 在一维区间上剪枝。平面（或 \\(k\\) 维）点集：问矩形里有哪些点，或最近邻。本课不维护 maxR。缺口是 k-d 树：循环选维、按该维坐标 BST 分裂。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(n\\) 个点在 \\(\\mathbb{R}^k\\)。正交范围查询。对半按 \\(x\\) 再按 \\(y\\)……建树，\\(\\Theta(n\\log n)\\) 可建（每次找中位数）。节点存点或存分裂值。查询矩形 \\(R\\)：当前分裂轴把空间切成两半，与 \\(R\\) 相交的一侧才递归；点在 \\(R\\) 内则报告。缺口是<strong>轴循环的二叉空间划分</strong>，不是 \\(k\\) 叉。</p><p>最坏查询可到 \\(\\Theta(n^{1-1/k}+m)\\) 一类界（平面约 \\(\\sqrt{n}\\)），平均更好。不要宣传成永远对数。</p><p><span class="marginnote">Bentley 1975, <em>CACM</em>。最近邻沿优先队列扩球，本课点名，不把所有启发式写完。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>静态：预排序各维或线性时间中位数。动态插入破坏平衡，可定期重建或用替罪羊思想，本课以静态为主。维数 \\(k\\) 大时，近邻与范围剪枝失效（距离集中），这是后课 LSH 的动机，本课只警告。</p>',9)),(e(),s(h,null,{default:r(()=>[p(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E7%82%B9%E9%9B%86%22%5D%20--%3E%20X%5B%22%E5%81%B6%E6%95%B0%E5%B1%82%3A%20%E6%8C%89%20x%20%E4%B8%AD%E4%BD%8D%E6%95%B0%22%5D%0A%20%20P%20--%3E%20Y%5B%22%E5%A5%87%E6%95%B0%E5%B1%82%3A%20%E6%8C%89%20y%20%E4%B8%AD%E4%BD%8D%E6%95%B0%22%5D%0A%20%20Q%5B%22%E6%9F%A5%E8%AF%A2%E7%9F%A9%E5%BD%A2%22%5D%20--%3E%20CLIP%5B%22%E4%B8%8E%E5%8D%8A%E5%B9%B3%E9%9D%A2%E7%9B%B8%E4%BA%A4%E6%89%8D%E8%BF%9B%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与四叉树：k-d 每次一轴二分；四叉按中点四块，形状不同。与 R 树：R 树包的是矩形 MBR，面向磁盘页。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>剪枝正确性：包围盒（由分裂历史推出）与 \\(R\\) 不相交则子树无点。更新一个点可能让树失衡，动态几何更常换 R 树或定期重建。</p><p>本课不进入限价簿或金融微观结构；点就是 \\(\\mathbb{R}^k\\) 记录。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>高维、磁盘块、或允许矩形重叠的分页索引：下一课 R 树。k-d 树不是 GIS 默认外存结构。</p><p>后课默认：内存静态点集正交查询可用 k-d。外存矩形用 R 树。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>k-d 树：轮换轴的多维 BST，范围查询可剪枝。</li><li>最坏不是 \\(O(\\log n)\\)；高维退化。</li><li>外存矩形索引进 R 树。</li><li>出处：Bentley, <em>CACM</em>, 1975；Preparata and Shamos。</li></ul>',9))])}const T=i(c,[["render",B]]);export{f as __pageData,T as default};
